"use client"

import * as React from "react"

import {
  EditableTable,
  type CellChange,
  type EditableColumn,
} from "./editable-table"
import { Badge } from "@/components/ui/badge"
import { Field, FieldLabel } from "@/components/ui/field"
import { Switch } from "@/components/ui/switch"

type Stage = "lead" | "qualified" | "proposal" | "won" | "lost"

export type Deal = {
  id: string
  name: string
  company: string
  owner: string
  stage: Stage
  value: number
  probability: number
}

const OWNERS = [
  "Renan Leonel",
  "Ana Souza",
  "João Pedro de Oliveira Neto",
  "Maria Eduarda Albuquerque",
  "Lucas Ferreira",
]

const STAGES: {
  value: Stage
  label: string
  tone: "gray" | "blue" | "amber" | "green" | "red"
}[] = [
  { value: "lead", label: "Lead", tone: "gray" },
  { value: "qualified", label: "Qualified", tone: "blue" },
  { value: "proposal", label: "Proposal", tone: "amber" },
  { value: "won", label: "Won", tone: "green" },
  { value: "lost", label: "Lost", tone: "red" },
]

const SAMPLE: Deal[] = [
  {
    id: "d1",
    name: "Annual renewal",
    company: "Northwind Logística",
    owner: "Ana Souza",
    stage: "proposal",
    value: 84000,
    probability: 70,
  },
  {
    id: "d2",
    name: "Seat expansion",
    company: "Café Pilão Digital",
    owner: "Renan Leonel",
    stage: "qualified",
    value: 32500,
    probability: 40,
  },
  {
    id: "d3",
    name: "Enterprise pilot",
    company: "Banco Aurora",
    owner: "João Pedro de Oliveira Neto",
    stage: "lead",
    value: 250000,
    probability: 15,
  },
  {
    id: "d4",
    name: "Analytics add-on",
    company: "Mercado Verde",
    owner: "Maria Eduarda Albuquerque",
    stage: "won",
    value: 18900,
    probability: 100,
  },
  {
    id: "d5",
    name: "Migration services",
    company: "Construtora Horizonte",
    owner: "Lucas Ferreira",
    stage: "proposal",
    value: 61200,
    probability: 55,
  },
  {
    id: "d6",
    name: "Support upgrade",
    company: "Clínica Bem Viver",
    owner: "Ana Souza",
    stage: "lost",
    value: 9600,
    probability: 0,
  },
  {
    id: "d7",
    name: "Multi-region rollout",
    company: "Transportes Rápido Sul",
    owner: "Renan Leonel",
    stage: "qualified",
    value: 142000,
    probability: 35,
  },
]

const brl = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "BRL",
  maximumFractionDigits: 0,
})

const wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms))

/**
 * Stand-in for your API. Deals over R$1M are refused, like a server-side rule
 * the client doesn't know about; `failAll` refuses everything.
 */
async function saveDeal(change: CellChange<Deal>, failAll: boolean) {
  await wait(600 + Math.random() * 600)
  if (failAll) throw new Error("The server is unavailable. Try again.")
  if (change.columnId === "value" && Number(change.value) > 1_000_000)
    throw new Error("Deals over R$1,000,000 need a manager's approval.")
}

const columns: EditableColumn<Deal>[] = [
  {
    id: "name",
    header: "Deal",
    value: (d) => d.name,
    editor: { type: "text", placeholder: "Deal name" },
    validate: (v) => (String(v) ? undefined : "A deal needs a name."),
    className: "min-w-44",
  },
  {
    id: "company",
    header: "Company",
    value: (d) => d.company,
    editor: { type: "text" },
    validate: (v) => (String(v) ? undefined : "Add the company."),
    className: "min-w-48",
  },
  {
    id: "owner",
    header: "Owner",
    value: (d) => d.owner,
    editor: {
      type: "select",
      options: OWNERS.map((o) => ({ value: o, label: o })),
    },
    className: "min-w-48 max-w-56",
  },
  {
    id: "stage",
    header: "Stage",
    value: (d) => d.stage,
    editor: {
      type: "select",
      options: STAGES.map(({ value, label }) => ({ value, label })),
    },
    render: (v) => {
      const stage = STAGES.find((s) => s.value === v)
      return stage ? <Badge tone={stage.tone}>{stage.label}</Badge> : v
    },
    className: "w-36",
  },
  {
    id: "value",
    header: "Value",
    value: (d) => d.value,
    editor: { type: "number", min: 0 },
    render: (v) => brl.format(Number(v)),
    align: "end",
    className: "w-36",
  },
  {
    id: "probability",
    header: "Probability",
    value: (d) => d.probability,
    editor: { type: "number", min: 0, max: 100 },
    render: (v) => `${v}%`,
    align: "end",
    className: "w-32",
  },
]

/** The pipeline: every cell saves on its own, optimistically. */
export function DealsTable({
  initialDeals = SAMPLE,
}: {
  initialDeals?: Deal[]
}) {
  const [deals, setDeals] = React.useState(initialDeals)
  const [failAll, setFailAll] = React.useState(false)

  const total = deals
    .filter((d) => d.stage !== "lost")
    .reduce((sum, d) => sum + d.value * (d.probability / 100), 0)

  return (
    <div className="flex flex-col gap-4">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <p className="text-sm text-muted-foreground">
          Weighted pipeline{" "}
          <span className="font-medium text-foreground tabular-nums">
            {brl.format(total)}
          </span>
        </p>
        <Field orientation="horizontal" className="w-auto">
          <Switch
            id="simulate-errors"
            checked={failAll}
            onCheckedChange={setFailAll}
          />
          <FieldLabel htmlFor="simulate-errors">
            Simulate server errors
          </FieldLabel>
        </Field>
      </div>
      <EditableTable
        aria-label="Deals"
        rows={deals}
        columns={columns}
        getRowId={(d) => d.id}
        getRowLabel={(d) => d.name}
        onCommit={async (change) => {
          await saveDeal(change, failAll)
          // Saved: apply it to the data before resolving, so the cell never
          // flashes the old value (with TanStack Query: setQueryData here).
          setDeals((prev) =>
            prev.map((d) =>
              d.id === change.rowId
                ? { ...d, [change.columnId]: change.value }
                : d
            )
          )
        }}
      />
    </div>
  )
}

"use client"

import * as React from "react"
import { cn } from "cn"
import { toast } from "sonner"

import { Input } from "@/components/ui/input"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Spinner } from "@/components/ui/spinner"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"

export type CellValue = string | number

export type CellEditor =
  | { type: "text"; placeholder?: string }
  | { type: "number"; min?: number; max?: number }
  | { type: "select"; options: { value: string; label: string }[] }

export type EditableColumn<Row> = {
  id: string
  header: string
  value: (row: Row) => CellValue
  /** How the cell edits; leave out for a read-only column. */
  editor?: CellEditor
  /** Display; defaults to the value as text. */
  render?: (value: CellValue, row: Row) => React.ReactNode
  /** Runs before saving; return a message to keep the old value. */
  validate?: (value: CellValue, row: Row) => string | undefined
  align?: "start" | "end"
  /** Width and other classes for the column's cells, e.g. `w-40`. */
  className?: string
}

export type CellChange<Row> = {
  row: Row
  rowId: string
  columnId: string
  value: CellValue
  previous: CellValue
}

type Pending = { value: CellValue }
type Pos = { r: number; c: number }

const keyOf = (rowId: string, columnId: string) => `${rowId}\u0000${columnId}`

function parse(
  editor: CellEditor,
  text: string
): CellValue | { error: string } {
  if (editor.type !== "number") return text.trim()
  const n = Number(text.replace(/[^\d.,-]/g, "").replace(",", "."))
  if (!text.trim() || Number.isNaN(n)) return { error: "Enter a number." }
  if (editor.min !== undefined && n < editor.min)
    return { error: `Enter ${editor.min} or more.` }
  if (editor.max !== undefined && n > editor.max)
    return { error: `Enter ${editor.max} or less.` }
  return n
}

/**
 * Optimistic, per-cell saves. The new value shows at once (`valueAt`) while
 * `onCommit` runs; a failure rolls it back, keeps an error and offers Retry.
 * The newest save per cell wins over an older one still in flight.
 */
function useOptimisticCells<Row>({
  getRowId,
  getRowLabel,
  onCommit,
}: {
  getRowId: (row: Row) => string
  getRowLabel: (row: Row) => string
  onCommit: (change: CellChange<Row>) => Promise<void>
}) {
  const [pending, setPending] = React.useState<Map<string, Pending>>(
    () => new Map()
  )
  const [errors, setErrors] = React.useState<Map<string, string>>(
    () => new Map()
  )
  const [status, setStatus] = React.useState("")
  const seq = React.useRef(0)
  // The newest save per cell; an older one settling never overwrites it.
  const latest = React.useRef(new Map<string, number>())

  const valueAt = (row: Row, column: EditableColumn<Row>) =>
    pending.get(keyOf(getRowId(row), column.id))?.value ?? column.value(row)

  const setError = (key: string, message: string | null) =>
    setErrors((prev) => {
      const next = new Map(prev)
      if (message) next.set(key, message)
      else next.delete(key)
      return next
    })

  const commit = async (
    row: Row,
    column: EditableColumn<Row>,
    value: CellValue
  ) => {
    const rowId = getRowId(row)
    const key = keyOf(rowId, column.id)
    const previous = column.value(row)
    const what = `${column.header} for ${getRowLabel(row)}`
    if (value === valueAt(row, column)) return

    const invalid = column.validate?.(value, row)
    if (invalid) {
      setError(key, invalid)
      setStatus(`${what} not saved: ${invalid}`)
      toast.error(invalid)
      return
    }

    // Optimistic: show the value now, remember which save this is.
    const mine = ++seq.current
    latest.current.set(key, mine)
    setError(key, null)
    setPending((prev) => new Map(prev).set(key, { value }))
    setStatus(`Saving ${what}…`)

    // Drops the optimistic value: on success the row now holds it, on
    // failure this is the rollback.
    const settle = () => {
      latest.current.delete(key)
      setPending((prev) => {
        const next = new Map(prev)
        next.delete(key)
        return next
      })
    }

    try {
      await onCommit({ row, rowId, columnId: column.id, value, previous })
      if (latest.current.get(key) !== mine) return // a newer save owns the cell
      settle()
      setStatus(`Saved ${what}.`)
    } catch (error) {
      if (latest.current.get(key) !== mine) return
      settle()
      const message =
        error instanceof Error ? error.message : "Couldn't save the change."
      setError(key, message)
      setStatus(`${what} not saved. ${message}`)
      toast.error(`Couldn't save ${what}`, {
        description: message,
        action: {
          label: "Retry",
          onClick: () => void commit(row, column, value),
        },
      })
    }
  }

  /** Parses typed text; a parse error marks the cell instead of saving. */
  const commitText = (row: Row, column: EditableColumn<Row>, text: string) => {
    if (!column.editor) return
    const parsed = parse(column.editor, text)
    if (typeof parsed !== "object") return void commit(row, column, parsed)
    setError(keyOf(getRowId(row), column.id), parsed.error)
    setStatus(
      `${column.header} for ${getRowLabel(row)} not saved: ${parsed.error}`
    )
  }

  return { pending, errors, status, valueAt, commitText }
}

/** Where an arrow, Home or End key moves the active cell (Ctrl/⌘ for corners). */
function moveFor(
  key: string,
  { r, c }: Pos,
  last: Pos,
  mod: boolean
): Pos | undefined {
  const moves: Record<string, Pos> = {
    ArrowUp: { r: r - 1, c },
    ArrowDown: { r: r + 1, c },
    ArrowLeft: { r, c: c - 1 },
    ArrowRight: { r, c: c + 1 },
    Home: mod ? { r: 0, c: 0 } : { r, c: 0 },
    End: mod ? last : { r, c: last.c },
  }
  return moves[key]
}

function CellDisplay<Row>({
  column,
  row,
  value,
  saving,
}: {
  column: EditableColumn<Row>
  row: Row
  value: CellValue
  saving: boolean
}) {
  const end = column.align === "end"
  return (
    <div
      className={cn(
        "flex h-10 min-w-0 items-center gap-2 px-3",
        end && "justify-end"
      )}
    >
      {saving && end && (
        <Spinner aria-label="Saving" className="size-3 text-muted-foreground" />
      )}
      <span className={cn("min-w-0 truncate", end && "tabular-nums")}>
        {column.render ? column.render(value, row) : String(value)}
      </span>
      {saving && !end && (
        <Spinner
          aria-label="Saving"
          className="ms-auto size-3 shrink-0 text-muted-foreground"
        />
      )}
    </div>
  )
}

function SaveSummary({ saving, failed }: { saving: number; failed: number }) {
  const plural = (n: number) => (n === 1 ? "change" : "changes")
  let text = "All changes saved"
  if (saving > 0) text = `Saving ${saving} ${plural(saving)}…`
  else if (failed > 0) text = `${failed} ${plural(failed)} not saved`
  return (
    <div className="flex items-center justify-between gap-3 px-1 text-xs text-muted-foreground">
      <p className="hidden sm:block">
        Enter or type to edit · Enter saves · Esc cancels
      </p>
      <p className="tabular-nums sm:ms-auto">{text}</p>
    </div>
  )
}

type Editing = { pos: Pos; initial: string; typed: boolean }

/**
 * A grid whose cells edit in place and save one at a time, optimistically.
 *
 * - The new value shows at once with a spinner while `onCommit` runs. Resolve
 *   after your data holds the new value (setState, `setQueryData`); reject to
 *   roll the cell back: it keeps an error ring and a toast offers Retry.
 *   A newer save of the same cell wins over an older one still in flight.
 * - Keyboard (WAI-ARIA data grid): arrows move, Home/End jump in the row,
 *   Enter or F2 or typing edits, Enter saves and moves down, Tab saves and
 *   moves right, Escape cancels. Double-click edits.
 */
export function EditableTable<Row>({
  rows,
  columns,
  getRowId,
  getRowLabel,
  onCommit,
  "aria-label": ariaLabel,
  className,
}: {
  rows: Row[]
  columns: EditableColumn<Row>[]
  getRowId: (row: Row) => string
  /** Names the row in announcements and toasts ("Value for Acme"). */
  getRowLabel: (row: Row) => string
  onCommit: (change: CellChange<Row>) => Promise<void>
  "aria-label": string
  className?: string
}) {
  const cellsState = useOptimisticCells({ getRowId, getRowLabel, onCommit })
  const { pending, errors, valueAt } = cellsState
  const [active, setActive] = React.useState<Pos>({ r: 0, c: 0 })
  const [editing, setEditing] = React.useState<Editing | null>(null)
  const cells = React.useRef(new Map<string, HTMLTableCellElement>())

  const focusCell = (pos: Pos) => {
    const r = Math.max(0, Math.min(rows.length - 1, pos.r))
    const c = Math.max(0, Math.min(columns.length - 1, pos.c))
    setActive({ r, c })
    cells.current.get(`${r}:${c}`)?.focus()
  }

  const startEdit = (pos: Pos, initial?: string) => {
    const column = columns[pos.c]
    const row = rows[pos.r]
    if (!column?.editor || !row) return
    setActive(pos)
    setEditing({
      pos,
      initial: initial ?? String(valueAt(row, column)),
      typed: initial !== undefined,
    })
  }

  const finishEdit = (
    text: string | null,
    move: Pos | null,
    { refocus = true }: { refocus?: boolean } = {}
  ) => {
    if (!editing) return
    const { pos } = editing
    const row = rows[pos.r]
    setEditing(null)
    if (text !== null && row) cellsState.commitText(row, columns[pos.c], text)
    if (refocus) focusCell(move ?? pos)
  }

  const onGridKeyDown = (e: React.KeyboardEvent) => {
    if (editing || e.target instanceof HTMLInputElement) return
    // The focused cell, not `active`: a key can land before focus re-renders.
    const td = (e.target as HTMLElement).closest<HTMLElement>("td[data-r]")
    if (!td) return
    const here = { r: Number(td.dataset.r), c: Number(td.dataset.c) }
    const mod = e.ctrlKey || e.metaKey
    const last = { r: rows.length - 1, c: columns.length - 1 }
    const move = moveFor(e.key, here, last, mod)
    if (move) {
      e.preventDefault()
      focusCell(move)
      return
    }
    if (e.key === "Enter" || e.key === "F2") {
      e.preventDefault()
      startEdit(here)
      return
    }
    const editor = columns[here.c]?.editor
    const typing = e.key.length === 1 && !mod && !e.altKey
    if (editor && editor.type !== "select" && typing) {
      // Typing replaces the value, like a spreadsheet.
      e.preventDefault()
      startEdit(here, e.key)
    }
  }

  const registerCell = (pos: string, el: HTMLTableCellElement | null) => {
    if (el) cells.current.set(pos, el)
    else cells.current.delete(pos)
  }

  return (
    <div className={cn("flex min-w-0 flex-col gap-2", className)}>
      <div className="overflow-hidden rounded-xl bg-card shadow-border">
        <Table
          role="grid"
          aria-label={ariaLabel}
          aria-rowcount={rows.length + 1}
          onKeyDown={onGridKeyDown}
          className="border-separate border-spacing-0"
        >
          <TableHeader>
            <TableRow className="hover:bg-transparent">
              {columns.map((column) => (
                <TableHead
                  key={column.id}
                  className={cn(
                    "h-9 bg-muted/40 px-3 text-xs text-muted-foreground shadow-[inset_0_-1px_0_var(--border)]",
                    column.align === "end" && "text-end",
                    column.className
                  )}
                >
                  {column.header}
                </TableHead>
              ))}
            </TableRow>
          </TableHeader>
          <TableBody>
            {rows.map((row, r) => {
              const rowId = getRowId(row)
              return (
                <TableRow key={rowId} className="border-0 hover:bg-transparent">
                  {columns.map((column, c) => (
                    <GridCell
                      key={column.id}
                      row={row}
                      column={column}
                      pos={{ r, c }}
                      value={valueAt(row, column)}
                      active={active.r === r && active.c === c}
                      editing={
                        editing?.pos.r === r && editing.pos.c === c
                          ? editing
                          : null
                      }
                      saving={pending.has(keyOf(rowId, column.id))}
                      error={errors.get(keyOf(rowId, column.id))}
                      label={`${column.header} for ${getRowLabel(row)}`}
                      register={registerCell}
                      onActivate={setActive}
                      onStartEdit={startEdit}
                      onDone={finishEdit}
                    />
                  ))}
                </TableRow>
              )
            })}
          </TableBody>
        </Table>
      </div>
      <SaveSummary saving={pending.size} failed={errors.size} />
      <p aria-live="polite" className="sr-only">
        {cellsState.status}
      </p>
    </div>
  )
}

function GridCell<Row>({
  row,
  column,
  pos,
  value,
  active,
  editing,
  saving,
  error,
  label,
  register,
  onActivate,
  onStartEdit,
  onDone,
}: {
  row: Row
  column: EditableColumn<Row>
  pos: Pos
  value: CellValue
  active: boolean
  editing: Editing | null
  saving: boolean
  error: string | undefined
  label: string
  register: (pos: string, el: HTMLTableCellElement | null) => void
  onActivate: (pos: Pos) => void
  onStartEdit: (pos: Pos) => void
  onDone: React.ComponentProps<typeof CellEditorControl>["onDone"]
}) {
  const editable = Boolean(column.editor)
  return (
    <TableCell
      ref={(el) => register(`${pos.r}:${pos.c}`, el)}
      role="gridcell"
      tabIndex={active && !editing ? 0 : -1}
      aria-readonly={!editable || undefined}
      aria-busy={saving || undefined}
      aria-invalid={error ? true : undefined}
      title={error}
      data-r={pos.r}
      data-c={pos.c}
      data-editable={editable || undefined}
      onFocus={() => {
        if (!active) onActivate(pos)
      }}
      onClick={() => onActivate(pos)}
      onDoubleClick={() => onStartEdit(pos)}
      className={cn(
        "relative h-10 p-0 shadow-[inset_0_-1px_0_var(--border)] outline-none focus-visible:z-10 focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-(--ds-focus-ring)",
        "data-editable:cursor-text data-editable:hover:bg-muted/40",
        error && "bg-destructive/5 shadow-[inset_0_0_0_1px_var(--destructive)]",
        column.className
      )}
    >
      {editing && column.editor ? (
        <CellEditorControl
          editor={column.editor}
          label={label}
          initial={editing.initial}
          typed={editing.typed}
          align={column.align}
          onDone={onDone}
          pos={pos}
        />
      ) : (
        <CellDisplay column={column} row={row} value={value} saving={saving} />
      )}
    </TableCell>
  )
}

function CellEditorControl({
  editor,
  label,
  initial,
  typed,
  align,
  pos,
  onDone,
}: {
  editor: CellEditor
  label: string
  initial: string
  /** Editing began with a keystroke (`initial` is that key). */
  typed: boolean
  align?: "start" | "end"
  pos: Pos
  onDone: (
    text: string | null,
    move: Pos | null,
    options?: { refocus?: boolean }
  ) => void
}) {
  const [text, setText] = React.useState(initial)
  const done = React.useRef(false)
  const finish = (
    value: string | null,
    move: Pos | null,
    options?: { refocus?: boolean }
  ) => {
    if (done.current) return
    done.current = true
    onDone(value, move, options)
  }

  if (editor.type === "select")
    return (
      <Select
        items={editor.options}
        defaultOpen
        value={initial}
        onValueChange={(v) => finish(v == null ? null : String(v), null)}
        onOpenChange={(open) => {
          if (!open) finish(null, null)
        }}
      >
        <SelectTrigger
          aria-label={label}
          className="h-10! w-full rounded-none border-0 bg-background px-3 shadow-none"
        >
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          {editor.options.map((option) => (
            <SelectItem key={option.value} value={option.value}>
              {option.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    )

  return (
    <Input
      autoFocus
      aria-label={label}
      value={text}
      inputMode={editor.type === "number" ? "decimal" : undefined}
      placeholder={editor.type === "text" ? editor.placeholder : undefined}
      onFocus={(e) => {
        // Opened by typing: caret after the typed key; otherwise select all.
        if (typed) e.target.setSelectionRange(1, 1)
        else e.target.select()
      }}
      onChange={(e) => setText(e.target.value)}
      onBlur={() => finish(text, null, { refocus: false })}
      onKeyDown={(e) => {
        if (e.key === "Enter") {
          e.preventDefault()
          finish(text, { r: pos.r + (e.shiftKey ? -1 : 1), c: pos.c })
        } else if (e.key === "Tab") {
          e.preventDefault()
          finish(text, { r: pos.r, c: pos.c + (e.shiftKey ? -1 : 1) })
        } else if (e.key === "Escape") {
          // Keep Escape from closing a surrounding dialog or sheet.
          e.preventDefault()
          e.stopPropagation()
          finish(null, null)
        }
      }}
      className={cn(
        "h-10 rounded-none border-0 bg-background px-3 shadow-none outline-2 -outline-offset-2 outline-(--ds-focus-ring) focus-visible:outline-2 dark:bg-background",
        align === "end" && "text-end tabular-nums"
      )}
    />
  )
}
